WITH enriched AS (SELECT *, NTILE(5) OVER (PARTITION BY channel ORDER BY discount_pct DESC, id) AS discount_pct_bucket, CUME_DIST() OVER (PARTITION BY channel, promo_code ORDER BY discount_pct DESC) AS discount_pct_cume_dist FROM promotions) SELECT CASE WHEN discount_pct_bucket >= 8 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_bucket_tier, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, COUNT_IF(channel = 'store') AS store_events FROM enriched GROUP BY CASE WHEN discount_pct_bucket >= 8 THEN 'LARGE' ELSE 'SMALL' END ORDER BY discount_pct_bucket_tier NULLS FIRST;
